  "witnessCode": "import {strict as assert} from 'node:assert';
import {test as describe, it} from 'node:test';
import normalizeUrl from '../index.js';

describe('stripWWW regression', () => {
  it('should not strip www. from hostnames with 1‑char TLD on base', () => {
    const result = normalizeUrl('www.example.a', {stripWWW: true});
    assert.match(result, /www\.example\.a/);
  });
});"
